contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (seed)); require(seed <= 1000000000000000000000000000000);
        require(address(this).balance >= seed);
        c.Command{value: seed}(address(this), bytes("")); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;
        uint256 ownerBalBefore = c.Owner().balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted || (address(c).balance == 0 && c.Owner().balance == ownerBalBefore + balBefore));
    }
}

